const __pageData = JSON.parse('{"title":"Iran","description":"","frontmatter":{"title":"Iran","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["iran","sanctions","oil","nuclear","hostage-crisis"],"sources":["raw/america-for-sale-part-3.md","raw/and-iran-iran-so-far-away.md","raw/assad-day-in-damascus.md","raw/badlands-blitz-episode-11.md","raw/badlands-blitz-episode-13.md","raw/badlands-blitz-episode-15.md","raw/badlands-blitz-episode-19.md","raw/badlands-blitz-episode-7.md","raw/badlands-brief-07c.md","raw/badlands-brief-05f.md","raw/badlands-brief-095.md","raw/badlands-brief-143.md","raw/badlands-brief-0bd.md","raw/badlands-brief-0fb.md","raw/badlands-brief-165.md","raw/badlands-brief-029.md","raw/badlands-brief-169.md","raw/badlands-brief-174.md","raw/badlands-brief-282.md","raw/badlands-brief-25c.md","raw/badlands-brief-2c0.md","raw/badlands-brief-2c5.md","raw/badlands-brief-3d4.md","raw/badlands-brief-311.md","raw/badlands-brief-40d.md","raw/badlands-brief-414.md","raw/badlands-brief-50d.md","raw/badlands-brief-52f.md","raw/badlands-brief-509.md","raw/badlands-brief-5a2.md","raw/badlands-brief-625.md","raw/badlands-brief-6a1.md","raw/badlands-brief-6f0.md","raw/badlands-brief-6b4.md","raw/badlands-brief-7b5.md","raw/badlands-brief-7c6.md","raw/badlands-brief-740.md","raw/badlands-brief-884.md","raw/badlands-brief-861.md","raw/badlands-brief-774.md","raw/badlands-brief-9ac.md","raw/badlands-brief-9ea.md","raw/badlands-brief-98d.md","raw/badlands-brief-a9f.md","raw/badlands-brief-a6b.md","raw/badlands-brief-b82.md","raw/badlands-brief-bb1.md","raw/badlands-brief-bf7.md","raw/badlands-brief-c07.md","raw/badlands-brief-d1a.md","raw/badlands-brief-c7b.md","raw/badlands-brief-db7.md","raw/badlands-brief-e9a.md","raw/badlands-brief-e9e.md","raw/badlands-brief-f17.md","raw/badlands-brief-eea.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-065.md","raw/badlands-news-brief-0cd.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-109.md","raw/badlands-news-brief-158.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-2db.md","raw/badlands-news-brief-2d5.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-426.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-447.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-50f.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-7c6.md","raw/badlands-news-brief-899.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/iran.md","filePath":"entities/iran.md","lastUpdated":null}');
